#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int a[100010];
int main() {
    int n, k;
    cin >> n >> k;
    for (int i = 1; i <=n; i++) {
        cin >> a[i];
    }
    int max_value = a[1],min_value=a[1];
    for (int i = 1; i <=n; i++) {
        max_value=max(max_value,a[i]);
        min_value=min(min_value,a[i]);
    }
    for (int i = 1; i <=n; i++) {
        if (a[i] > k) {
            a[i] = max_value;
        } else if (a[i] < k) {
            a[i] = min_value;
        }
        if (i != n) {
            cout << a[i] << " ";
        } else {
            cout << a[i] << endl;
        }
    }

    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string n;
    cin >> n;

    for (int row = 0; row < 5; row++) {
        string line = "";
        for (char digit : n) {
            if (digit == '0') {
                if (row == 0 || row == 4) {
                    line += ".....";
                } else {
                    line += ".***.";
                }
            } else if (digit == '1') {
                line += "****.";
            } else if (digit == '2') {
                if (row == 0) {
                    line += ".....";
                } else if (row == 1) {
                    line += "****.";
                } else if (row == 2) {
                    line += ".....";
                } else if (row == 3) {
                    line += ".****";
                } else {
                    line += ".....";
                }
            } else if (digit == '3') {
                if (row == 0) {
                    line += ".....";
                } else if (row == 1) {
                    line += "****.";
                } else if (row == 2) {
                    line += ".....";
                } else if (row == 3) {
                    line += "****.";
                } else {
                    line += ".....";
                }
            }
        }
        cout << line << endl;
    }

    return 0;
}
